import math

def check_condition(n):
    """
    Checks if k^2 === 1 (mod n) for all k coprime to n.
    """
    if n < 2:
        return False

    # Check all k from 1 up to n-1
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check if k^2 - 1 is a multiple of n
            if (k*k - 1) % n != 0:
                return False
    return True

solutions = []
for n in range(2, 21):
    if check_condition(n):
        solutions.append(n)

print(f"Solutions found in range 2 <= n <= 20: {solutions}")
